from itertools import combinations

weeks = 6
num_groups = 9
size = 4
golfers = 36

def check_solution(schedule):
    """schedule[w][p] = group of golfer p in week w"""
    pairs_seen = set()
    for w in range(weeks):
        grps = [[] for _ in range(num_groups)]
        for p in range(golfers):
            grps[schedule[w][p]].append(p)
        for g in range(num_groups):
            if len(grps[g]) != size:
                return False, f"Week {w} group {g} has {len(grps[g])} members"
            for p1, p2 in combinations(grps[g], 2):
                pair = (min(p1,p2), max(p1,p2))
                if pair in pairs_seen:
                    return False, f"Pair {pair} repeated in week {w}"
                pairs_seen.add(pair)
    return True, "OK"

