# Let me use a faster conflict counting and smarter local search
from itertools import combinations
import random
import math

weeks = 6
num_groups = 9
size = 4
golfers = 36

def make_schedule():
    """Create initial schedule - week 0 is fixed as 0-3, 4-7, etc."""
    schedule = []
    for w in range(weeks):
        perm = list(range(golfers))
        random.shuffle(perm)
        week = [0] * golfers
        for p_idx, p in enumerate(perm):
            week[p] = p_idx // size
        schedule.append(week)
    return schedule

def compute_pair_conflicts(schedule):
    """Returns dict of pair -> count"""
    pair_count = {}
    for w in range(weeks):
        grps = [[] for _ in range(num_groups)]
        for p in range(golfers):
            grps[schedule[w][p]].append(p)
        for g in range(num_groups):
            members = grps[g]
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = (members[i], members[j]) if members[i] < members[j] else (members[j], members[i])
                    pair_count[pair] = pair_count.get(pair, 0) + 1
    return pair_count

def total_conflicts(pair_count):
    return sum(c - 1 for c in pair_count.values() if c > 1)

# Faster: maintain pair counts incrementally
def fast_local_search(max_iter=200000):
    # Initialize
    schedule = make_schedule()

    # Compute initial pair counts
    pair_count = compute_pair_conflicts(schedule)
    conflicts = total_conflicts(pair_count)

    best_schedule = [list(w) for w in schedule]
    best_conflicts = conflicts

    for it in range(max_iter):
        if conflicts == 0:
            break

        # Pick random week and two golfers in different groups
        w = random.randint(0, weeks-1)
        p1 = random.randint(0, golfers-1)
        p2 = random.randint(0, golfers-1)

        g1 = schedule[w][p1]
        g2 = schedule[w][p2]
        if g1 == g2:
            continue

        # Get group members
        grp1 = [p for p in range(golfers) if schedule[w][p] == g1]
        grp2 = [p for p in range(golfers) if schedule[w][p] == g2]

        # Compute delta: pairs involving p1 in grp1 and p2 in grp2 change
        # Pairs that will be removed: (p1, x) for x in grp1\{p1}, (p2, x) for x in grp2\{p2}
        # Pairs that will be added: (p1, x) for x in grp2\{p2}, (p2, x) for x in grp1\{p1}

        removed_pairs = []
        for x in grp1:
            if x != p1:
                pair = (min(p1,x), max(p1,x))
                removed_pairs.append(pair)
        for x in grp2:
            if x != p2:
                pair = (min(p2,x), max(p2,x))
                removed_pairs.append(pair)

        added_pairs = []
        for x in grp2:
            if x != p2:
                pair = (min(p1,x), max(p1,x))
                added_pairs.append(pair)
        for x in grp1:
            if x != p1:
                pair = (min(p2,x), max(p2,x))
                added_pairs.append(pair)

        # Compute delta conflicts
        delta = 0
        for pair in removed_pairs:
            c = pair_count.get(pair, 0)
            if c > 1:
                delta -= 1
        for pair in added_pairs:
            c = pair_count.get(pair, 0)
            if c >= 1:
                delta += 1

        if delta <= 0:
            # Accept
            schedule[w][p1] = g2
            schedule[w][p2] = g1
            for pair in removed_pairs:
                pair_count[pair] = pair_count.get(pair, 0) - 1
            for pair in added_pairs:
                pair_count[pair] = pair_count.get(pair, 0) + 1
            conflicts += delta
            if conflicts < best_conflicts:
                best_conflicts = conflicts
                best_schedule = [list(w) for w in schedule]
        elif random.random() < 0.01:  # small random acceptance
            schedule[w][p1] = g2
            schedule[w][p2] = g1
            for pair in removed_pairs:
                pair_count[pair] = pair_count.get(pair, 0) - 1
            for pair in added_pairs:
                pair_count[pair] = pair_count.get(pair, 0) + 1
            conflicts += delta

    return best_schedule, best_conflicts

random.seed(42)
best_overall = None
best_val = float('inf')

for trial in range(20):
    result, conf = fast_local_search(200000)
    print(f"Trial {trial}: {conf}")
    if conf < best_val:
        best_val = conf
        best_overall = result
    if conf == 0:
        break

print(f"Best: {best_val}")
